from urllib.parse import urlparse
import boto3

if not isinstance(output_dir, 'litdata.streaming.resolver.Dir'):
    raise ValueError("output_dir must be an instance of Dir")
if output_dir.url is None:
    return

parsed_url = urlparse(output_dir.url)
s3 = boto3.client('s3')

bucket_name = parsed_url.netloc
prefix = parsed_url.path.lstrip('/')

try:
    s3.head_object(Bucket=bucket_name, Key=f'{prefix}/index.json')
    raise ValueError(f"Directory {output_dir.url} already contains an index file")
except Exception as e:
    try:
        s3.delete_objects(Bucket=bucket_name, Prefix=prefix)
    except Exception as e:
        print(f"Error deleting objects in bucket {bucket_name}: {str(e)}")
    raise e

