elif isinstance(batch, (tuple, list)):
    return type(batch)(to_cuda(item, device, ignore_list) for item in batch)

# If the input is a torch.Tensor, move it to the specified CUDA device
elif isinstance(batch, torch.Tensor):
    return batch.to(device)

# If the input is not a supported type, raise a ValueError
else:
    raise ValueError("Unsupported input type")

