# Define the safe log1p function using generate_safe_fn
def generate_safe_fn(fn, derivative):
    def safe_fn(x, *args):
        clipped_x = jnp.clip(x, -1e10, 1e10)  # Clip inputs to a valid range
        return fn(clipped_x, *args)
    def safe_fn_dot(x, *args):
        clipped_x = jnp.clip(x, -1e10, 1e10)  # Clip inputs to a valid range
        return derivative(clipped_x, *args)
    return safe_fn, safe_fn_dot

